public class Solution {
  // "指数退避 + 投递次数等于重试次数"版：既没有阶梯表，也没有"原始那一次"，
  // 于是最大重试 3 次的消息只投 3 次就没了（少一次），而间隔在长尾上比官方阶梯密得多。
  public static int[] nextDeliverPlan(int mode, int failedAttempt, int maxRetry, int orderlyIntervalMs,
                                      int invisibleMs, int costMs) {
    if (mode != 0 && mode != 1 && mode != 2) throw new IllegalArgumentException("unknown consumer mode");
    if (failedAttempt < 0) throw new IllegalArgumentException("negative failed attempt");
    if (maxRetry < 0) throw new IllegalArgumentException("maxRetry must be non-negative");
    if (orderlyIntervalMs < 0) throw new IllegalArgumentException("orderly interval must be non-negative");
    if (mode == 2 && invisibleMs <= 0) throw new IllegalArgumentException("invisible duration must be positive");
    if (costMs < 0) throw new IllegalArgumentException("negative cost");

    int total = failedAttempt;
    if (failedAttempt > maxRetry) return new int[] {0, 0, 1, total};
    long delay = 1000L << Math.min(failedAttempt, 20);
    return new int[] {(int) delay, failedAttempt + 1, 0, total};
  }
}
